    public function fetch_balance($params = array ()): array {
        /**
         * query for $balance and get the amount of funds available for trading or funds locked in orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->owner] the wallet address to query $balance for
         * @return {array} a [$balance structure](https://docs.ccxt.com/#/?id=$balance-structure)
         */
        $this->load_markets();
        $owner = null;
        list($owner, $params) = $this->ensure_owner_address($params);
        $ownerAddress = $this->address_with0x_prefix($owner);
        $result = array(
            'info' => array(),
            'timestamp' => null,
            'datetime' => null,
        );
        $currencies = array();
        $marketValues = is_array($this->markets) ? array_values($this->markets) : array();
        for ($i = 0; $i < count($marketValues); $i++) {
            $market = $marketValues[$i];
            $baseCode = $this->safe_string($market, 'base');
            $baseId = $this->safe_string_lower($market, 'baseId');
            $marketInfo = $this->safe_value($market, 'info', array());
            $baseInfo = $this->safe_value($marketInfo, 'base', array());
            $decimals = $this->safe_string($baseInfo, 'decimals');
            if (($baseCode !== null) && ($baseId !== null) && ($decimals !== null)) {
                if (!(is_array($currencies) && array_key_exists($baseCode, $currencies))) {
                    $currencies[$baseCode] = array( 'id' => $baseId, 'decimals' => $decimals );
                }
            }
        }
        $currencyCodes = is_array($currencies) ? array_keys($currencies) : array();
        for ($i = 0; $i < count($currencyCodes); $i++) {
            $code = $currencyCodes[$i];
            $currencyInfo = $currencies[$code];
            $tokenAddress = $this->safe_string($currencyInfo, 'id');
            $decimals = $this->safe_string($currencyInfo, 'decimals');
            try {
                $balanceRaw = $this->fetch_erc20_balance($tokenAddress, $ownerAddress);
                $balanceString = $this->convert_token_amount($balanceRaw, $decimals);
                $balance = $this->parse_number($balanceString);
                $result[$code] = array(
                    'free' => $balance,
                    'used' => 0, // CoW doesn't lock funds, orders are intent-based
                    'total' => $balance,
                );
            } catch (Exception $e) {
                $result[$code] = array(
                    'free' => 0,
                    'used' => 0,
                    'total' => 0,
                );
            }
        }
        return $this->safe_balance($result);
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetch all $trades made by the user
