    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array ()): array {
        /**
         * create a trade order on CoW Protocol
         *
         * @see https://docs.cow.fi/cow-protocol/reference/apis/orderbook
         *
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the $quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->validFor] order validity duration in seconds (default 30)
         * @param {int} [$params->validTo] unix timestamp when the order expires
         * @param {bool} [$params->partiallyFillable] whether the order can be partially filled (default false)
         * @param {string} [$params->appData] app data for the order (32-byte hex string)
         * @param {string} [$params->receiver] the address to receive the bought tokens (defaults to sender)
         * @param {string} [$params->from] the address placing the order (defaults to walletAddress)
         * @param {array} [$params->quoteRequest] override parameters for the $quote request
         * @return {array} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $this->check_required_credentials();
        if (($this->privateKey === null) || ($this->privateKey === '')) {
            throw new AuthenticationError($this->id . ' createOrder() requires exchange.privateKey to be set');
        }
        $owner = null;
        list($owner, $params) = $this->ensure_owner_address($params);
        $receiverParam = $this->safe_string_lower($params, 'receiver', $owner);
        $fromParam = $this->safe_string_lower($params, 'from', $owner);
        $params = $this->omit($params, array( 'receiver', 'from' ));
        $defaultKind = ($side === 'sell') ? 'sell' : 'buy';
        $kind = $this->safe_string_lower($params, 'kind', $defaultKind);
        if (($type !== 'limit') && ($type !== 'market')) {
            throw new NotSupported($this->id . ' createOrder() supports $market and limit order types');
        }
        if (($type === 'limit') && ($price === null)) {
            throw new ArgumentsRequired($this->id . ' createOrder() requires a $price argument for limit orders');
        }
        $marketInfo = $this->safe_value($market, 'info', array());
        $baseInfo = $this->safe_value($marketInfo, 'base', array());
        $quoteInfo = $this->safe_value($marketInfo, 'quote', array());
        $baseDecimals = $this->safe_string($baseInfo, 'decimals');
        $quoteDecimals = $this->safe_string($quoteInfo, 'decimals');
        $partiallyFillable = $this->safe_bool($params, 'partiallyFillable', false);
        $validFor = $this->safe_integer($params, 'validFor', $this->safe_integer($this->options, 'defaultValidFor', 30));
        $currentSeconds = $this->seconds();
        $validTo = $this->safe_integer($params, 'validTo', $currentSeconds . $validFor);
        $appData = $this->safe_string($params, 'appData', $this->safe_string($this->options, 'defaultAppData'));
        $quoteRequestOverrides = $this->safe_dict($params, 'quoteRequest');
        $params = $this->omit($params, array( 'kind', 'partiallyFillable', 'validFor', 'validTo', 'appData', 'quoteRequest' ));
        $isSellOrder = ($kind === 'sell');
        $sellToken = $isSellOrder ? $this->safe_string_lower($market, 'baseId') : $this->safe_string_lower($market, 'quoteId');
        $buyToken = $isSellOrder ? $this->safe_string_lower($market, 'quoteId') : $this->safe_string_lower($market, 'baseId');
        $sellTokenDecimals = $isSellOrder ? $baseDecimals : $quoteDecimals;
        $buyTokenDecimals = $isSellOrder ? $quoteDecimals : $baseDecimals;
        $amountString = $this->number_to_string($amount);
        $sellAmountRaw = null;
        $buyAmountRaw = null;
        if ($isSellOrder) {
            $sellAmountRaw = $this->amount_to_token_amount($amountString, $sellTokenDecimals);
        } else {
            $buyAmountRaw = $this->amount_to_token_amount($amountString, $buyTokenDecimals);
        }
        $receiverAddress = $this->address_with0x_prefix($receiverParam);
        $fromAddress = $this->address_with0x_prefix($fromParam);
        $quoteRequest = $this->extend(array(
            'sellToken' => $this->address_with0x_prefix($sellToken),
            'buyToken' => $this->address_with0x_prefix($buyToken),
            'receiver' => $receiverAddress,
            'from' => $fromAddress,
            'kind' => $kind,
            'validTo' => $validTo,
            'partiallyFillable' => $partiallyFillable,
            'sellTokenBalance' => 'erc20',
            'buyTokenBalance' => 'erc20',
        ), $quoteRequestOverrides);
        if ($isSellOrder) {
            $quoteRequest['sellAmountBeforeFee'] = $this->safe_string($quoteRequest, 'sellAmountBeforeFee', $sellAmountRaw);
            if ($type === 'limit') {
                $priceString = $this->number_to_string($price);
                $costDecimal = Precise::string_mul($amountString, $priceString);
                $buyAmountRawLimit = $this->amount_to_token_amount($costDecimal, $buyTokenDecimals);
                $quoteRequest['buyAmountAfterFee'] = $this->safe_string($quoteRequest, 'buyAmountAfterFee', $buyAmountRawLimit);
            }
        } else {
            $quoteRequest['buyAmountAfterFee'] = $this->safe_string($quoteRequest, 'buyAmountAfterFee', $buyAmountRaw);
            if ($type === 'limit') {
                $priceString = $this->number_to_string($price);
                $costDecimal = Precise::string_mul($amountString, $priceString);
                $sellAmountRawLimit = $this->amount_to_token_amount($costDecimal, $sellTokenDecimals);
                $quoteRequest['sellAmountBeforeFee'] = $this->safe_string($quoteRequest, 'sellAmountBeforeFee', $sellAmountRawLimit);
            }
        }
        $quoteResponse = $this->publicPostApiV1Quote ($quoteRequest);
        $quote = $this->safe_dict($quoteResponse, 'quote', $quoteResponse);
        $orderBody = array(
            'sellToken' => $this->address_with0x_prefix($this->safe_string($quote, 'sellToken', $sellToken)),
            'buyToken' => $this->address_with0x_prefix($this->safe_string($quote, 'buyToken', $buyToken)),
            'receiver' => $this->address_with0x_prefix($this->safe_string($quote, 'receiver', $receiverParam)),
            'sellAmount' => $this->safe_string($quote, 'sellAmount', $sellAmountRaw),
            'buyAmount' => $this->safe_string($quote, 'buyAmount', $this->safe_string($quoteRequest, 'buyAmountAfterFee')),
            'validTo' => $this->safe_integer($quote, 'validTo', $validTo),
            'appData' => $this->safe_string($quote, 'appData', $appData),
            'feeAmount' => '0', // CoW Protocol requires fee to be zero (fee is already included in $sellAmount)
            'kind' => $this->safe_string_lower($quote, 'kind', $kind),
            'partiallyFillable' => $this->safe_bool($quote, 'partiallyFillable', $partiallyFillable),
            'sellTokenBalance' => $this->safe_string_lower($quote, 'sellTokenBalance', 'erc20'),
            'buyTokenBalance' => $this->safe_string_lower($quote, 'buyTokenBalance', 'erc20'),
        );
        $signingScheme = $this->safe_string_lower($quote, 'signingScheme', 'eip712');
        $orderBody['signingScheme'] = $signingScheme;
        $orderBody['signature'] = $this->sign_order_payload($orderBody, $signingScheme);
        $signerAddr = $this->derive_wallet_address_from_private_key();
        $orderBody['from'] = strtolower($this->address_with0x_prefix($signerAddr));
        $autoApprove = $this->safe_bool($this->options, 'autoApprove', true);
        if ($autoApprove) {
            $sellTokenAddress = $this->safe_string($orderBody, 'sellToken');
            if ($sellTokenAddress !== null) {
                $vaultRelayer = $this->get_vault_relayer_option();
                $sellAmount = $this->safe_string($orderBody, 'sellAmount', '0');
                $feeAmount = $this->safe_string($orderBody, 'feeAmount', '0');
                $requiredAmount = Precise::string_add($sellAmount, $feeAmount);
                try {
                    $currentAllowance = $this->check_erc20_allowance($sellTokenAddress, $this->hex_with0x_prefix($signerAddr), $vaultRelayer);
                    if (Precise::string_lt($currentAllowance, $requiredAmount)) {
                        $this->log('Insufficient allowance detected. Approving VaultRelayer...');
                        $approvalResult = $this->approve_erc20($sellTokenAddress, $vaultRelayer);
                        $this->log('Approval transaction:', $approvalResult['txHash']);
                        $this->sleep(5000);
                    }
                } catch (Exception $e) {
                    $message = $this->safe_string($e, 'message', $this->json($e));
                    throw new ExchangeError($this->id . ' createOrder() failed to ensure allowance => ' . $message);
                }
            }
        }
        $response = $this->publicPostApiV1Orders ($orderBody);
        $uid = $this->safe_string_2($response, 'orderUid', 'uid');
        $parsed = $this->parse_order($this->extend(array(), $orderBody, array( 'uid' => $uid, 'info' => $response, 'status' => 'open' )), $market);
        return $this->extend($parsed, array( 'info' => $response ));
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array ()): array {
        /**
         * cancels an open order
         *
         * @see https://docs.cow.fi/cow-protocol/reference/apis/orderbook
         *
         * @param {string} $id order $id (UID)
         * @param {string} $symbol unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->signingScheme] 'eip712' or 'ethsign' (default 'eip712')
         * @return {array} An [order structure](https://docs.ccxt.com/#/?$id=order-structure)
         */
        $this->load_markets();
        $this->check_required_credentials();
        if (($this->privateKey === null) || ($this->privateKey === '')) {
            throw new AuthenticationError($this->id . ' cancelOrder() requires exchange.privateKey to be set');
        }
        $owner = null;
        list($owner, $params) = $this->ensure_owner_address($params);
        $signingScheme = $this->safe_string_lower($params, 'signingScheme', 'eip712');
        $params = $this->omit($params, array( 'signingScheme' ));
        $orderUids = array( $id );
        $requestBody = array(
            'orderUids' => $orderUids,
            'signature' => $this->sign_order_cancellation($orderUids, $signingScheme),
            'signingScheme' => $signingScheme,
        );
        $headers = array( 'Content-Type' => 'application/json' );
        $response = $this->request('api/v1/orders', 'public', 'DELETE', $params, $headers, $this->json($requestBody));
        $market = ($symbol !== null) ? $this->market($symbol) : null;
        return $this->parse_order(array( 'uid' => $id, 'status' => 'canceled', 'info' => $response, 'owner' => $owner ), $market);
    }

    public function cancel_all_orders(?string $symbol = null, $params = array ()): array {
        /**
         * cancel all open orders
         *
         * @see https://docs.cow.fi/cow-protocol/reference/apis/orderbook
         *
         * @param {string} $symbol unified market $symbol, only orders in the market of this $symbol are cancelled when $symbol is not null
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->owner] the wallet address to cancel orders for
         * @param {string} [$params->signingScheme] 'eip712' or 'ethsign' (default 'eip712')
         * @return {array[]} a list of [$order structures](https://docs.ccxt.com/#/?id=$order-structure)
         */
        $this->load_markets();
        $openOrders = $this->fetch_open_orders($symbol, null, null, $params);
        if (strlen($openOrders) === 0) {
            return array();
        }
        $results = array();
        for ($i = 0; $i < count($openOrders); $i++) {
            $order = $openOrders[$i];
            $orderId = $this->safe_string($order, 'id');
            if ($orderId !== null) {
                try {
                    $result = $this->cancel_order($orderId, $symbol, $params);
                    $results[] = $result;
                } catch (Exception $e) {
                    $results[] = $this->extend($order, array( 'status' => 'failed', 'info' => $e ));
                }
            }
        }
        return $results;
    }

    public function ensure_owner_address(array $params = array ()): array {
        $owner = $this->safe_string_lower_2($params, 'owner', 'walletAddress');
        $modifiedParams = $this->omit($params, array( 'owner', 'walletAddress' ));
        $derivedOwner = $this->derive_wallet_address_from_private_key();
        if ($owner === null) {
            $optionOwner = $this->safe_string_lower($this->options, 'walletAddress');
            if ($optionOwner !== null) {
                $owner = $optionOwner;
            } elseif (($this->walletAddress !== null) && (gettype($this->walletAddress) === 'string') && ($this->walletAddress !== '')) {
                $owner = strtolower($this->walletAddress);
            } elseif ($derivedOwner !== null) {
                $owner = $derivedOwner;
            }
        }
        if (($owner !== null) && str_starts_with(!$owner, '0x')) {
            $owner = '0x' . $owner;
        }
        if (($derivedOwner !== null) && ($owner !== null) && (strtolower($owner) !== $derivedOwner)) {
            throw new AuthenticationError($this->id . ' walletAddress mismatch between provided $owner and private key');
        }
        if ($owner === null) {
            throw new ArgumentsRequired($this->id . ' requires a wallet address; set exchange.walletAddress, exchange.options["walletAddress"] or provide $params["owner"]');
        }
        return array( strtolower($owner), $modifiedParams );
    }

    public function hex_with0x_prefix(?string $value): ?string {
        if ($value === null) {
            return $value;
        }
        return str_starts_with($value, '0x') ? $value : ('0x' . $value);
    }

    public function address_with0x_prefix(?string $value): ?string {
        return $this->hex_with0x_prefix($value);
    }

    public function normalize_private_key(?string $privateKey): ?string {
        if ($privateKey === null) {
            return $privateKey;
        }
        return $this->hex_with0x_prefix($privateKey);
    }

    public function derive_wallet_address_from_private_key(): ?string {
        $normalizedKey = $this->normalize_private_key($this->privateKey);
        if (($normalizedKey === null) || ($normalizedKey === '')) {
            return null;
        }
        $keyHex = $this->remove0x_prefix($normalizedKey);
        if (strlen($keyHex) !== 64) {
            throw new AuthenticationError($this->id . ' privateKey must be a 32-byte hex string');
        }
        $privateKeyBytes = $this->base16_to_binary($keyHex);
        $publicKey = secp256k1.getPublicKey ($privateKeyBytes, false);
        $hashBytes = keccak (mb_substr($publicKey, 1));
        $addressBytes = mb_substr($hashBytes, -20);
        $address = '0x' . bin2hex($addressBytes);
        return strtolower($address);
    }

    public function amount_to_token_amount(?string $amountString, ?string $decimals): ?string {
        if (($amountString === null) || ($decimals === null)) {
            return null;
        }
        $decimalsString = $this->number_to_string($decimals);
        $precision = $this->parse_precision($decimalsString);
        return Precise::string_div($amountString, $precision);
    }

    public function get_chain_id_option() {
        $network = $this->safe_string($this->options, 'network', 'mainnet');
        $chains = $this->safe_value($this->options, 'chainIds', array());
        $chainId = $this->safe_integer($chains, $network);
        if ($chainId === null) {
            throw new ExchangeError($this->id . ' unsupported $network ' . $network . ' for chain id resolution');
        }
        return $chainId;
    }

    public function get_verifying_contract_option() {
        $network = $this->safe_string($this->options, 'network', 'mainnet');
        $contracts = $this->safe_value($this->options, 'verifyingContracts', array());
        $verifyingContract = $this->safe_string($contracts, $network);
        if ($verifyingContract === null) {
            throw new ExchangeError($this->id . ' unsupported $network ' . $network . ' for verifying contract resolution');
        }
        return $this->hex_with0x_prefix($verifyingContract);
    }

    public function get_vault_relayer_option() {
        $network = $this->safe_string($this->options, 'network', 'mainnet');
        $relayers = $this->safe_value($this->options, 'vaultRelayers', array());
        $vaultRelayer = $this->safe_string($relayers, $network);
        if ($vaultRelayer === null) {
            throw new ExchangeError($this->id . ' unsupported $network ' . $network . ' for vault relayer resolution');
        }
        return $this->hex_with0x_prefix($vaultRelayer);
    }

    public function get_rpc_url_option() {
        $network = $this->safe_string($this->options, 'network', 'mainnet');
        $rpcUrls = $this->safe_value($this->options, 'rpcUrls', array());
        return $this->safe_string($rpcUrls, $network);
    }

    public function fetch_erc20_balance(?string $tokenAddress, ?string $ownerAddress) {
        $rpcUrl = $this->get_rpc_url_option();
        if ($rpcUrl === null) {
            throw new ExchangeError($this->id . ' fetchERC20Balance() requires rpcUrls[' . $this->options['network'] . '] to be configured');
        }
        $ownerPadded = $this->remove0x_prefix($ownerAddress).padStart (64, '0');
        // ERC20 balanceOf(address) = 0x70a08231
        $data = '0x70a08231' . $ownerPadded;
        $request = array(
            'jsonrpc' => '2.0',
            'method' => 'eth_call',
            'params' => array(
                array(
                    'to' => $tokenAddress,
                    'data' => $data,
                ),
                'latest',
            ),
            'id' => 1,
        );
        $response = $this->fetch($rpcUrl, 'POST', array( 'Content-Type' => 'application/json' ), $this->json($request));
        $result = $this->safe_string($response, 'result', '0x0');
        $errorResult = $this->safe_value($response, 'error');
        if ($errorResult !== null) {
            throw new ExchangeError($this->id . ' fetchERC20Balance() RPC error => ' . $this->json($errorResult));
        }
        if ($result === '0x') {
            return '0';
        }
        $hexValue = $this->remove0x_prefix($result);
        if ($hexValue === '') {
            return '0';
        }
        return BigInt ('0x' . (string) $hexValue);
    }

    public function check_erc20_allowance(?string $tokenAddress, ?string $ownerAddress, ?string $spenderAddress) {
        $rpcUrl = $this->get_rpc_url_option();
        if ($rpcUrl === null) {
            throw new ExchangeError($this->id . ' checkERC20Allowance() requires rpcUrls[' . $this->options['network'] . '] to be configured');
        }
        $ownerPadded = $this->remove0x_prefix($ownerAddress).padStart (64, '0');
        $spenderPadded = $this->remove0x_prefix($spenderAddress).padStart (64, '0');
        $data = '0xdd62ed3e' . $ownerPadded . $spenderPadded;
        $request = array(
            'jsonrpc' => '2.0',
            'method' => 'eth_call',
            'params' => array(
                array(
                    'to' => $tokenAddress,
                    'data' => $data,
                ),
                'latest',
            ),
            'id' => 1,
        );
        $response = $this->fetch($rpcUrl, 'POST', array( 'Content-Type' => 'application/json' ), $this->json($request));
        $result = $this->safe_string($response, 'result', '0');
        if ($result === '0') {
            $errorResult = $this->safe_value($response, 'error');
            if ($errorResult !== null) {
                throw new ExchangeError($this->id . ' checkERC20Allowance() failed to fetch allowance => ' . $this->json($response));
            }
        }
        return $result;
    }

    public function approve_erc20(?string $tokenAddress, ?string $spenderAddress, ?string $amount = null) {
        $rpcUrl = $this->get_rpc_url_option();
        if ($rpcUrl === null) {
            throw new ExchangeError($this->id . ' approveERC20() requires rpcUrls[' . $this->options['network'] . '] to be configured');
        }
        $privateKey = $this->normalize_private_key($this->privateKey);
        $ownerAddress = $this->derive_wallet_address_from_private_key();
        $approvalAmount = ($amount !== null) ? $amount : '0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff';
        $spenderPadded = $this->remove0x_prefix($spenderAddress).padStart (64, '0');
        $amountHex = $approvalAmount;
        if (str_starts_with($amountHex, '0x')) {
            $amountHex = '0x' . $this->remove0x_prefix($amountHex).padStart (64, '0');
        } else {
            $numericValue = intval($amountHex);
            $amountHex = '0x' . $numericValue->toString (16).padStart (64, '0');
        }
        $data = '0x095ea7b3' . $spenderPadded . $this->remove0x_prefix($amountHex);
        $nonceRequest = array(
            'jsonrpc' => '2.0',
            'method' => 'eth_getTransactionCount',
            'params' => array( $this->hex_with0x_prefix($ownerAddress), 'latest' ),
            'id' => 2,
        );
        $nonceResponse = $this->fetch($rpcUrl, 'POST', array( 'Content-Type' => 'application/json' ), $this->json($nonceRequest));
        $nonce = $this->safe_string($nonceResponse, 'result');
        $gasPriceRequest = array(
            'jsonrpc' => '2.0',
            'method' => 'eth_gasPrice',
            'params' => array(),
            'id' => 3,
        );
        $gasPriceResponse = $this->fetch($rpcUrl, 'POST', array( 'Content-Type' => 'application/json' ), $this->json($gasPriceRequest));
        $gasPrice = $this->safe_string($gasPriceResponse, 'result');
        $chainId = $this->get_chain_id_option();
        $tx = array(
            'nonce' => $nonce,
            'gasPrice' => $gasPrice,
            'gasLimit' => '0x186a0', // 100000 in hex
            'to' => $tokenAddress,
            'value' => '0x0',
            'data' => $data,
            'chainId' => $chainId,
        );
        $txFields = [
            $tx['nonce'],
            $tx['gasPrice'],
            $tx['gasLimit'],
            $tx['to'],
            $tx['value'],
            $tx['data'],
            '0x' . $chainId->toString (16),
            '0x',
            '0x',
        ];
        $rlpEncoded = $this->encode_rlp($txFields);
        $txHash = '0x' . bin2hex(keccak ($this->base16_to_binary($this->remove0x_prefix($rlpEncoded))));
        $privateKeyBytes = $this->base16_to_binary($this->remove0x_prefix($privateKey));
        $hashBytes = $this->base16_to_binary($this->remove0x_prefix($txHash));
        $signature = secp256k1.sign ($hashBytes, $privateKeyBytes);
        $compact = $signature->toCompactHex ();
        $r = mb_substr($compact, 0, 64 - 0);
        $s = mb_substr($compact, 64);
        $recovery = $signature->recovery;
        $v = ($chainId * 2) + 35 . $recovery;
        $signedTxFields = [
            $tx['nonce'],
            $tx['gasPrice'],
            $tx['gasLimit'],
            $tx['to'],
            $tx['value'],
            $tx['data'],
            '0x' . $v->toString (16),
            '0x' . $r,
            '0x' . $s,
        ];
        $signedRlp = $this->encode_rlp($signedTxFields);
        $broadcastRequest = array(
            'jsonrpc' => '2.0',
            'method' => 'eth_sendRawTransaction',
            'params' => array( $signedRlp ),
            'id' => 4,
        );
        $broadcastResponse = $this->fetch($rpcUrl, 'POST', array( 'Content-Type' => 'application/json' ), $this->json($broadcastRequest));
        $txHashResult = $this->safe_string($broadcastResponse, 'result');
        $error = $this->safe_value($broadcastResponse, 'error');
        if ($error !== null) {
            throw new ExchangeError($this->id . ' approveERC20() failed => ' . $this->json($error));
        }
        return array(
            'txHash' => $txHashResult,
            'token' => $tokenAddress,
            'spender' => $spenderAddress,
            'amount' => $approvalAmount,
        );
    }

    public function encode_rlp_item(string $value): string {
        $hex = $value;
        if (str_starts_with(!$hex, '0x')) {
            $hex = '0x' . $hex;
        }
        $hex = strtolower($this->remove0x_prefix($hex));
        while (strlen($hex) > 1 && $hex[0] === '0') {
            $hex = mb_substr($hex, 1);
        }
        if (strlen($hex) === 0) {
            $hex = '0';
        }
        if (strlen(fmod($hex), 2) !== 0) {
            $hex = '0' . $hex;
        }
        if ($hex === '00' || $hex === '') {
            return '80';
        }
        $length = strlen($hex) / 2;
        if ($length === 1 && intval($hex, 16) < 128) {
            return $hex;
        }
        if ($length < 56) {
            return (128 . $length).toString (16).padStart (2, '0') . $hex;
        }
        $lengthHex = $length->toString (16);
        $lengthOfLength = (int) ceil(strlen($lengthHex) / 2);
        $paddedLengthHex = str_pad($lengthHex, $lengthOfLength * 2, '0', STR_PAD_LEFT);
        return (183 . $lengthOfLength).toString (16) . $paddedLengthHex . $hex;
    }

    public function encode_rlp(array $fields): string {
        $encoded = array();
        for ($i = 0; $i < count($fields); $i++) {
            $encoded[] = $this->encode_rlp_item($fields[$i]);
        }
        $concatenated = implode('', $encoded);
        $totalLength = strlen($concatenated) / 2;
        if ($totalLength < 56) {
            return '0x' . (192 . $totalLength).toString (16).padStart (2, '0') . $concatenated;
        }
        $lengthHex = $totalLength->toString (16);
        $lengthOfLength = (int) ceil(strlen($lengthHex) / 2);
        $paddedLengthHex = str_pad($lengthHex, $lengthOfLength * 2, '0', STR_PAD_LEFT);
        return '0x' . (247 . $lengthOfLength).toString (16) . $paddedLengthHex . $concatenated;
    }

    public function compute_typed_data_digest(array $domain, array $types, array $message) {
        $encoder = TypedDataEncoder;
        if (is_callable($encoder->hash)) {
            return $encoder->hash ($domain, $types, $message);
        }
        $encoded = $encoder->encode ($domain, $types, $message);
        $encodedBinary = $this->base16_to_binary(mb_substr($encoded, 2));
        $digestBytes = keccak ($encodedBinary);
        return '0x' . bin2hex($digestBytes);
    }

    public function hash_ethereum_signed_message(?string $messageHex) {
        if ($messageHex === null) {
            return null;
        }
        $binaryMessage = $this->base16_to_binary($this->remove0x_prefix($messageHex));
        if (strlen($binaryMessage) !== 32) {
            throw new ExchangeError($this->id . ' hashEthereumSignedMessage() requires a 32-byte digest hex string');
        }
        $messageLength = $this->binary_length($binaryMessage);
        // eslint-disable-next-line quotes
        $prefixString = "\x19Ethereum Signed Message:\n" . $this->number_to_string($messageLength);
        $prefixBinary = $this->encode($prefixString);
        $prefixed = $this->binary_concat($prefixBinary, $binaryMessage);
        $digestBytes = keccak ($prefixed);
        return '0x' . bin2hex($digestBytes);
    }

    public function sign_digest(?string $digest, ?string $privateKey, bool $usePersonalSign = false) {
        $normalizedKey = $this->normalize_private_key($privateKey);
        if ($digest === null || $normalizedKey === null) {
            return null;
        }
        $hashToSign = $digest;
        if ($usePersonalSign) {
            $hashToSign = $this->hash_ethereum_signed_message($digest);
        }
        $digestBytes = $this->base16_to_binary($this->remove0x_prefix($hashToSign));
        $privateKeyBytes = $this->base16_to_binary($this->remove0x_prefix($normalizedKey));
        $signature = secp256k1.sign ($digestBytes, $privateKeyBytes);
        $compact = $signature->toCompactHex ();
        $recovery = $signature->recovery;
        $r = mb_substr($compact, 0, 64 - 0);
        $s = mb_substr($compact, 64);
        $vValue = $recovery + 27;
        $vHex = $vValue->toString (16).padStart (2, '0');
        return '0x' . $r . $s . $vHex;
    }

    public function sign_order_payload(array $order, ?string $signingScheme = 'eip712') {
        $privateKey = $this->normalize_private_key($this->privateKey);
        $chainId = $this->get_chain_id_option();
        $verifyingContract = $this->get_verifying_contract_option();
        $domain = array(
            'name' => 'Gnosis Protocol',
            'version' => 'v2',
            'chainId' => $chainId,
            'verifyingContract' => $verifyingContract,
        );
        $receiverAddress = $this->safe_string($order, 'receiver');
        $normalizedReceiver = '0x0000000000000000000000000000000000000000';
        if ($receiverAddress !== null) {
            $normalizedReceiver = getAddress ($this->hex_with0x_prefix($receiverAddress));
        }
        $message = array(
            'sellToken' => getAddress ($this->hex_with0x_prefix($order['sellToken'])),
            'buyToken' => getAddress ($this->hex_with0x_prefix($order['buyToken'])),
            'receiver' => $normalizedReceiver,
            'sellAmount' => $this->safe_string($order, 'sellAmount'),
            'buyAmount' => $this->safe_string($order, 'buyAmount'),
            'validTo' => $this->safe_integer($order, 'validTo'),
            'appData' => $this->hex_with0x_prefix($this->safe_string($order, 'appData')),
            'feeAmount' => $this->safe_string($order, 'feeAmount', '0'),
            'kind' => $this->safe_string_lower($order, 'kind'),
            'partiallyFillable' => $this->safe_bool($order, 'partiallyFillable', false),
            'sellTokenBalance' => $this->safe_string_lower($order, 'sellTokenBalance', 'erc20'),
            'buyTokenBalance' => $this->safe_string_lower($order, 'buyTokenBalance', 'erc20'),
        );
        $types = array(
            'Order' => array(
                array( 'name' => 'sellToken', 'type' => 'address' ),
                array( 'name' => 'buyToken', 'type' => 'address' ),
                array( 'name' => 'receiver', 'type' => 'address' ),
                array( 'name' => 'sellAmount', 'type' => 'uint256' ),
                array( 'name' => 'buyAmount', 'type' => 'uint256' ),
                array( 'name' => 'validTo', 'type' => 'uint32' ),
                array( 'name' => 'appData', 'type' => 'bytes32' ),
                array( 'name' => 'feeAmount', 'type' => 'uint256' ),
                array( 'name' => 'kind', 'type' => 'string' ),
                array( 'name' => 'partiallyFillable', 'type' => 'bool' ),
                array( 'name' => 'sellTokenBalance', 'type' => 'string' ),
                array( 'name' => 'buyTokenBalance', 'type' => 'string' ),
            ),
        );
        $typedDataEncoder = new TypedDataEncoder ($types);
        $domainSeparator = TypedDataEncoder.hashDomain ($domain);
        $structHash = $typedDataEncoder->hash ($message);
        $prefix = '0x1901';
        $encoded = $prefix . mb_substr($domainSeparator, 2) . mb_substr($structHash, 2);
        $digest = '0x' . bin2hex(keccak ($this->base16_to_binary(mb_substr($encoded, 2))));
        $usePersonalSign = ($signingScheme === 'ethsign');
        return $this->sign_digest($digest, $privateKey, $usePersonalSign);
    }

    public function sign_order_cancellation(array $orderUids, ?string $signingScheme = 'eip712') {
        $privateKey = $this->normalize_private_key($this->privateKey);
        $chainId = $this->get_chain_id_option();
        $verifyingContract = $this->get_verifying_contract_option();
        $domain = array(
            'name' => 'Gnosis Protocol',
            'version' => 'v2',
            'chainId' => $chainId,
            'verifyingContract' => $verifyingContract,
        );
        $typeString = 'OrderCancellations(bytesarray() $orderUids)';
        $typeHash = '0x' . bin2hex(keccak ($typeString));
        $concatenatedHashes = '';
        for ($i = 0; $i < count($orderUids); $i++) {
            $uid = $this->hex_with0x_prefix($orderUids[$i]);
            $uidBytes = $this->base16_to_binary(mb_substr($uid, 2));
            $uidHash = keccak ($uidBytes);
            $concatenatedHashes .= bin2hex($uidHash);
        }
        $arrayHash = '0x' . bin2hex(keccak ($this->base16_to_binary($concatenatedHashes)));
        $structHashInput = mb_substr($typeHash, 2) . mb_substr($arrayHash, 2);
        $structHash = '0x' . bin2hex(keccak ($this->base16_to_binary($structHashInput)));
        $domainSeparator = TypedDataEncoder.hashDomain ($domain);
        $prefix = '0x1901';
        $encoded = $prefix . mb_substr($domainSeparator, 2) . mb_substr($structHash, 2);
        $digest = '0x' . bin2hex(keccak ($this->base16_to_binary(mb_substr($encoded, 2))));
        if ($signingScheme === 'ethsign') {
            $prefixedDigest = $this->hash_ethereum_signed_message($digest);
            return $this->sign_digest($prefixedDigest, $privateKey, false);
        } else {
            return $this->sign_digest($digest, $privateKey, false);
        }
    }

    public function compare_quote_with_other_exchanges(?string $symbol, float $amount, array $otherExchanges = [], $params = array ()) {
        /**
         * get a $quote from CoW Protocol and compare it with quotes from other exchanges
         *
         * @see https://docs.cow.fi/cow-protocol/reference/apis/orderbook
         *
         * @param {string} $symbol unified $market $symbol
         * @param {float} $amount the $amount of base currency to trade
         * @param {array[]} $otherExchanges array of $exchange instances to compare quotes with
         * @param {array} [$params] extra parameters specific to the $exchange API endpoint
         * @param {string} [$params->receiver] the address to receive the bought tokens
         * @param {string} [$params->from] the address placing the order
         * @param {int} [$params->validFor] $quote validity duration in seconds
         * @return {array} a $comparison object with CoW $quote and other $exchange quotes
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $marketInfo = $this->safe_value($market, 'info', array());
        $baseInfo = $this->safe_value($marketInfo, 'base', array());
        $quoteInfo = $this->safe_value($marketInfo, 'quote', array());
        $baseDecimals = $this->safe_string($baseInfo, 'decimals');
        $quoteDecimals = $this->safe_string($quoteInfo, 'decimals');
        $owner = null;
        list($owner, $params) = $this->ensure_owner_address($params);
        $receiverParam = $this->safe_string_lower($params, 'receiver', $owner);
        $fromParam = $this->safe_string_lower($params, 'from', $owner);
        $amountString = $this->number_to_string($amount);
        $sellAmountRaw = $this->amount_to_token_amount($amountString, $baseDecimals);
        $nowSeconds = $this->seconds();
        $validFor = $this->safe_integer($params, 'validFor', $this->safe_integer($this->options, 'defaultValidFor', 30));
        $validTo = $this->safe_integer($params, 'validTo', $nowSeconds . $validFor);
        $params = $this->omit($params, array( 'validFor', 'validTo', 'receiver', 'from' ));
        $quoteRequest = $this->extend(array(
            'sellToken' => $this->address_with0x_prefix($market['baseId']),
            'buyToken' => $this->address_with0x_prefix($market['quoteId']),
            'sellAmountBeforeFee' => $sellAmountRaw,
            'receiver' => $this->address_with0x_prefix($receiverParam),
            'from' => $this->address_with0x_prefix($fromParam),
            'kind' => 'sell',
            'partiallyFillable' => false,
            'validTo' => $validTo,
            'sellTokenBalance' => 'erc20',
            'buyTokenBalance' => 'erc20',
        ), $params);
        $quoteResponse = $this->publicPostApiV1Quote ($quoteRequest);
        $quote = $this->safe_dict($quoteResponse, 'quote', $quoteResponse);
        $cowSellAmountRaw = $this->safe_string($quote, 'sellAmount', $sellAmountRaw);
        $cowBuyAmountRaw = $this->safe_string($quote, 'buyAmount');
        $cowFeeRaw = $this->safe_string($quote, 'feeAmount', '0');
        $cowBuyAmount = $this->convert_token_amount($cowBuyAmountRaw, $quoteDecimals);
        $effectiveAmount = $this->convert_token_amount($cowSellAmountRaw, $baseDecimals);
        $cowFee = $this->convert_token_amount($cowFeeRaw, $baseDecimals);
        $cowPrice = null;
        if (($cowBuyAmount !== null) && ($effectiveAmount !== null) && (!Precise::string_eq($effectiveAmount, '0'))) {
            $cowPrice = $this->parse_number(Precise::string_div($cowBuyAmount, $effectiveAmount));
        }
        $comparisons = array();
        for ($i = 0; $i < count($otherExchanges); $i++) {
            $exchange = $otherExchanges[$i];
            $comparison = array(
                'exchange' => null,
                'available' => null,
                'cost' => null,
                'price' => null,
                'slippage' => null,
                'error' => null,
                'info' => null,
            );
            try {
                if ($exchange === null) {
                    continue;
                }
                $comparison['exchange'] = $exchange->id;
                if (($exchange->has !== null) && ($exchange->has['fetchOrderBook'] !== null) && !$exchange->has['fetchOrderBook']) {
                    $comparison['error'] = 'fetchOrderBook not supported';
                    $comparisons[] = $comparison;
                    continue;
                }
                $exchange->loadMarkets ();
                $orderBook = $exchange->fetchOrderBook ($symbol);
                $comparison['info'] = $orderBook;
                $asks = $this->safe_list($orderBook, 'asks', $orderBook['asks']);
                $remaining = $amountString;
                $cost = '0';
                $filled = '0';
                for ($j = 0; $j < count($asks); $j++) {
                    $level = $asks[$j];
                    $price = $this->number_to_string($level[0]);
                    $size = $this->number_to_string($level[1]);
                    if (($price === null) || ($size === null)) {
                        continue;
                    }
                    if (Precise::string_le($remaining, '0')) {
                        break;
                    }
                    $tradeAmount = Precise::string_min($remaining, $size);
                    $cost = Precise::string_add($cost, Precise::string_mul($tradeAmount, $price));
                    $filled = Precise::string_add($filled, $tradeAmount);
                    $remaining = Precise::string_sub($remaining, $tradeAmount);
                }
                if (Precise::string_le($filled, '0')) {
                    $comparison['error'] = 'insufficient liquidity';
                    $comparisons[] = $comparison;
                    continue;
                }
                $filledNumber = $this->parse_number($filled);
                $costNumber = $this->parse_number($cost);
                $priceNumber = null;
                if ($filledNumber !== null && $filledNumber > 0 && $costNumber !== null) {
                    $priceNumber = $costNumber / $filledNumber;
                }
                $slippage = null;
                if (($cowPrice !== null) && ($priceNumber !== null) && ($cowPrice !== 0)) {
                    $slippage = ($priceNumber - $cowPrice) / $cowPrice;
                }
                $comparison = $this->extend($comparison, array(
                    'available' => $filledNumber,
                    'cost' => $costNumber,
                    'price' => $priceNumber,
                    'slippage' => $slippage,
                    'remaining' => $this->parse_number($remaining),
                ));
            } catch (Exception $error) {
                $errorMessage = $this->json($error);
                if ($error instanceof Error) {
                    $errorMessage = $error->message;
                }
                $comparison['error'] = $errorMessage;
            }
            $comparisons[] = $comparison;
        }
        return array(
            'symbol' => $symbol,
            'amount' => $amount,
            'price' => $this->parse_number($cowPrice),
            'buyAmount' => $this->parse_number($cowBuyAmount),
            'sellAmount' => $this->parse_number($effectiveAmount),
            'fee' => $this->parse_number($cowFee),
            'info' => $quoteResponse,
            'comparisons' => $comparisons,
        );
    }

    public function wait_for_order(?string $id, ?string $symbol = null, ?string $status = null, $params = array ()): array {
        /**
         * polls the exchange until an $order reaches a terminal $status
         *
         * @see https://docs.cow.fi/cow-protocol/reference/apis/orderbook
         *
         * @param {string} $id $order $id (UID)
         * @param {string} $symbol unified market $symbol
         * @param {string} [$status] specific $status to wait for (defaults to any terminal $status)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->pollingDelay] delay between polling requests in milliseconds (default 2000)
         * @param {int} [$params->timeout] maximum time to wait in milliseconds (default 60000)
         * @return {array} an [$order structure](https://docs.ccxt.com/#/?$id=$order-structure)
         */
        $this->load_markets();
        $options = $this->safe_value($this->options, 'waitForOrder', array());
        $statuses = $this->safe_value($options, 'statuses', array( 'closed', 'canceled', 'expired', 'rejected' ));
        $targetStatuses = ($status === null) ? $statuses : array( $status );
        $defaultPollingDelay = $this->safe_integer($options, 'pollingDelay', 2000);
        $defaultTimeout = $this->safe_integer($options, 'timeout', 60000);
        $pollingDelay = $this->safe_integer($params, 'pollingDelay', $defaultPollingDelay);
        $timeout = $this->safe_integer($params, 'timeout', $defaultTimeout);
        $fetchParams = $this->omit($params, array( 'pollingDelay', 'timeout' ));
        $deadline = $this->milliseconds() . $timeout;
        // eslint-disable-next-line no-constant-condition
        while (true) {
            $order = $this->fetch_order($id, $symbol, $fetchParams);
            $orderStatus = $this->safe_string($order, 'status');
            if ($this->in_array($orderStatus, $targetStatuses)) {
                return $order;
            }
            if ($this->milliseconds() > $deadline) {
                throw new InvalidOrder($this->id . ' waitForOrder() timed out waiting for $order ' . $id . ' to reach $status ' . implode(',', $targetStatuses));
            }
            $this->sleep($pollingDelay);
        }
    }

    public function handle_errors(?int $httpCode, string $reason, string $url, string $method, array $headers, string $body, $response, $requestHeaders, $requestBody) {
        if ($response === null) {
            return;
        }
        $errorType = $this->safe_string($response, 'errorType');
        if ($errorType !== null) {
            $description = $this->safe_string($response, 'description');
            $feedback = $this->id . ' ' . ($description === null ? $body : $description);
            $errors = array(
                'DuplicatedOrder' => '\\ccxt\\InvalidOrder',
                'OrderAlreadyExists' => '\\ccxt\\InvalidOrder',
                'InvalidOrder' => '\\ccxt\\InvalidOrder',
                'InsufficientFee' => '\\ccxt\\InvalidOrder',
                'InsufficientFunds' => '\\ccxt\\InsufficientFunds',
                'UnknownOrder' => '\\ccxt\\OrderNotFound',
                'OrderNotFound' => '\\ccxt\\OrderNotFound',
                'OrderExpired' => '\\ccxt\\OrderNotFound',
                'InvalidSignature' => '\\ccxt\\AuthenticationError',
                'UnsupportedSellToken' => '\\ccxt\\BadSymbol',
                'UnsupportedBuyToken' => '\\ccxt\\BadSymbol',
                'UnsupportedSigningScheme' => '\\ccxt\\AuthenticationError',
                'InvalidAppData' => '\\ccxt\\BadRequest',
                'SellAmountDoesNotCoverFee' => '\\ccxt\\InvalidOrder',
                'SlippageTooLarge' => '\\ccxt\\InvalidOrder',
                'NoLiquidity' => '\\ccxt\\InvalidOrder',
            );
            $Exception = $this->safe_value($errors, $errorType, '\\ccxt\\ExchangeError');
            throw new $Exception($feedback);
        }
        $errorsList = $this->safe_list($response, 'errors');
        if ($errorsList !== null) {
            for ($i = 0; $i < count($errorsList); $i++) {
                $error = $errorsList[$i];
                $type = $this->safe_string($error, 'errorType');
                if ($type !== null) {
                    $description = $this->safe_string($error, 'description');
                    $feedback = $this->id . ' ' . ($description === null ? $this->json($error) : $description);
                    $errors = array(
                        'DuplicatedOrder' => '\\ccxt\\InvalidOrder',
                        'InvalidOrder' => '\\ccxt\\InvalidOrder',
                        'InsufficientFee' => '\\ccxt\\InvalidOrder',
                        'InsufficientFunds' => '\\ccxt\\InsufficientFunds',
                        'UnsupportedSellToken' => '\\ccxt\\BadSymbol',
                        'UnsupportedBuyToken' => '\\ccxt\\BadSymbol',
                        'NoLiquidity' => '\\ccxt\\InvalidOrder',
                    );
                    $Exception = $this->safe_value($errors, $type, '\\ccxt\\ExchangeError');
                    throw new $Exception($feedback);
                }
            }
        }
        $status = $this->safe_string($response, 'status');
        if ($status !== null) {
            $knownOrderStatuses = array( 'open', 'pending', 'pending-solver-submission', 'presignatureAwaiting', 'presignaturePending', 'fulfilled', 'expired', 'solved', 'cancelled', 'canceled', 'retracted', 'failed' );
            if (!$this->in_array($status, $knownOrderStatuses)) {
                if (($status !== 'success') && ($status !== 'ok')) {
                    $description = $this->safe_string($response, 'description');
                    $feedback = $this->id . ' ' . ($description === null ? $body : $description);
                    throw new ExchangeError($feedback);
                }
            }
        }
    }
}
